        "beatSystemCopy": {
            "saveTheCatTitle": "Save the Cat",
            "saveTheCatDesc": "Met l'accent sur les beats émotionnels clairs et l'engagement du public.\n\nUtilisez-le lorsque vous voulez des points de retournement nets, des inversions visibles et une forte impression d'élan de mise en page à la fin de la configuration jusqu'à la finale.\n\nIdéal pour : fiction commerciale, scénarios, genres à concept élevé\nProfil Momentum : Configuration -> Virage médian -> Paiement de clôture",
            "saveTheCatExamples": "Exemples : The Hunger Games, le Martien, la faute de nos étoiles.",
            "saveTheCatSourceLabel": "Les livres de Save the Cat de Jessica Brody",
            "herosJourneyTitle": "Voyage des héros",
            "herosJourneyDesc": "Suit le départ, la transformation, l'épreuve et le retour.\n\nUtilisez-le lorsque vous souhaitez un arc mythique ou axé sur l'identité avec une transformation intérieure et extérieure visible.\n\nIdéal pour : histoires de quêtes, fiction spéculative, passage à l'âge adulte, voyages de transformation\nProfil Momentum : Départ -> Essais -> Ordeal -> Retour avec changement",
            "herosJourneyExamples": "Exemples : Star Wars, The Hobbit, A Wizard of EarthSea.",
            "herosJourneySourceLabel": "Le parcours de l'écrivain de Christopher Vogler",
            "classicDramaticTitle": "Structure dramatique classique",
            "classicDramaticDesc": "Met l'accent sur la pression de la scène, les tournants, les choix essentiels et les résultats consécutifs.\n\nUtilisez-le lorsque vous souhaitez tester si chaque scène crée des mouvements à travers les conflits et les changements.\n\nIdéal pour : Fiction littéraire, Drame, Travail de scène étroitement édité, Révision Pass\nProfil Momentum : Configuration → Complication → Pression → Choix central → Résultat",
            "classicDramaticExamples": "Exemples : fierté et préjugés, Hamlet, le parrain.",
            "podcastArcTitle": "Arc narratif de podcast",
            "podcastArcDesc": "Forme la narration parlée autour du crochet, de la configuration, du développement et du gain.\n\nUtilisez-le lorsque vous souhaitez une forte rétention de l'auditeur et une progression verbale propre.\n\nIdéal pour : podcasts, essais audio, monologues, non-fiction racontée\nProfil Momentum : Crochet -> Encadrement -> Développement -> Paiement",
            "podcastArcExamples": "Exemples : épisodes de podcast narratif, épisodes d'histoires menés par une interview, segments audio documentaires.",
            "youtubeExplainerTitle": "arc explicatif youtube",
            "youtubeExplainerDesc": "Organise l'enseignement et l'explication autour de la curiosité, de la clarté et de la progression.\n\nUtilisez-le lorsque vous souhaitez qu'un spectateur comprenne rapidement quelque chose tout en restant engagé.\n\nIdéal pour : explicateurs, vidéos éducatives, commentaires, tutoriels\nProfil de Momentum : Crochet -> Promesse -> Répartition -> À emporter",
            "youtubeExplainerExamples": "Exemples : explicateurs éducatifs, canaux de commentaires, narration axée sur les didacticiels.",
            "documentaryArcTitle": "Arc narratif documentaire",
            "documentaryArcDesc": "Équilibre la chronologie, le contexte, les enjeux et les conséquences dans les événements retouchés.\n\nUtilisez-le lorsque vous avez besoin de guider le public à travers des événements réels sans perdre de l'élan.\n\nIdéal pour : Rédaction de l'histoire, Structure documentaire, Storytelling non-fiction, Chronologie\nProfil Momentum : Contexte -> Accumulation -> Pivot -> Conséquence",
            "documentaryArcExamples": "Exemples : documentaires historiques, chapitres d'histoire narrative, reconstructions d'événements.",
            "romanceLadderTitle": "Échelle de tropes de romance",
            "romanceLadderDesc": "Suivre l'attraction, la tension, la vulnérabilité, la rupture et le gain émotionnel.\n\nUtilisez-le lorsque l'arc de relation émotionnelle est le principal moteur de l'investissement des lecteurs.\n\nIdéal pour : Romance, Intrigues secondaires romantiques, Passes de la chimie des personnages\nProfil d'élan : étincelle -> tension -> vulnérabilité -> rupture -> Union/décision",
            "romanceLadderExamples": "Exemples : ennemis aux amants, proximité forcée, combustion lente.",
            "thrillerLadderTitle": "Échelle d'escalade de thriller",
            "thrillerLadderDesc": "Développe la pression à travers le danger, la révélation, les inversions et le rétrécissement des options.\n\nUtilisez-le lorsque vous voulez que chaque phase resserre les risques et réduise les choix sécuritaires du protagoniste.\n\nIdéal pour : Thrillers, suspense, intrigues de chasse, récits de survie\nProfil Momentum : Menace -> Pursuite -> Inversion -> Compression -> Confrontation",
            "thrillerLadderExamples": "Exemples : The Fugitive, Gone Girl, Le silence des agneaux.",
            "customTitle": "système personnalisé",
            "customDesc": "Concevez votre propre cadre structurel pour ce manuscrit. Définissez les beats qui comptent pour votre histoire, qu'ils suivent un arc classique ou Suivez la progression spécifique au genre.\n\nLes systèmes personnalisés peuvent représenter des tropes, des virages thématiques, des jalons d'investigation, des phases historiques ou tout rythme structurel que vous souhaitez mesurer.",
            "customExamples": "Exemples : flux de travail nouveaux personnalisés, systèmes de révision sur mesure, structures de classe.",
            "blankCustomTitle": "coutume vide",
            "blankCustomDesc": "Commence vide afin que vous puissiez concevoir votre propre structure à partir de zéro.\n\nUtilisez-le lorsqu'aucun des objectifs de la bibliothèque ne correspond à votre processus ou si vous souhaitez un modèle spécifique au projet.\n\nIdéal pour : conception de beat personnalisé, expérimentation, structures hybrides, enseignement de votre propre méthode\nProfil Momentum : défini par l'auteur",
            "blankCustomExamples": "Commencez avec au moins 3 beats. Nommez chaque beat par fonction, pas par thème. Utilisez une progression claire telle que l'ouverture -> la pression -> le décalage. Ajouter ou La réorganisation ne bat uniquement lorsque chacun a un objectif structurel distinct."
        },
