            "glossaryLineSpaceTerm": "Espace de ligne",
            "glossaryLineSpaceDef": "Espace vertical entre les lignes de base. serré (1,0) est à un seul interligne ; La norme (1.5) se lit proprement en version imprimée ; Airy (2.0) est un éditeur convivial double-espace; Personnalisé vous permet de composer n'importe quelle valeur de 0,8 à 3.",
