            "glossaryRunningHeaderTerm": "En-tête de course",
            "glossaryRunningHeaderDef": "Le texte répétitif en haut de chaque page intérieure (titre du livre, auteur, contexte de scène, numéro de page, etc.). Les pages paires et impaires peuvent porter Différents contenus sur des livres de page.",
            "glossaryEvenOddTerm": "Page pair vs impair",
            "glossaryEvenOddDef": "Convention d'impression : les numéros de page pair (2, 4, 6 …) sont assis sur le côté gauche (verso) d'un spread ouvert ; Les nombres impairs (1, 3, 5 …) sont assis sur la droite (recto). La page 1 est toujours recto. Survolez n'importe quelle carte de coin pour son côté de page spécifique.",
            "glossaryPresetTerm": "préréglé",
            "glossaryPresetDef": "Dispositions d'en-tête courantes câblées en un clic. Utilisez Personnaliser par coin ci-dessous pour remplacer les emplacements individuels – remplacez le calque au-dessus du préréglage.",
            "glossaryHeaderFontDef": "\"Herit Body\" réutilise la police de caractères. \"Sans\" bascule les en-têtes sur un sans-serif (une convention de mise en page standard).",
            "glossaryLetterSpacingDef": "Un suivi supplémentaire entre les lettres dans les têtes de course, dans les unités FontSpec (par exemple, 15.0 produit les majuscules larges dans la mise en page professionnelle). 0 signifie le suivi par défaut.",
